import React from 'react';
import { useTheme } from '../context/ThemeContext';
import { themes, ThemeType } from '../config/theme';

const DarkModeToggle: React.FC = () => {
  const { isDarkMode, toggleDarkMode, theme, setTheme } = useTheme();

  return (
    <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2">
      {/* Theme Selector */}
      {/* <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-3">
        <div className="flex gap-2">
          {Object.keys(themes).map((themeKey) => {
            const currentTheme = themes[themeKey as ThemeType];
            return (
              <button
                key={themeKey}
                onClick={() => setTheme(themeKey as ThemeType)}
                className={`w-8 h-8 rounded-full ${
                  currentTheme.light.primary
                } ${
                  theme === themeKey ? 'ring-2 ring-offset-2 ring-gray-400' : ''
                }`}
                aria-label={`Switch to ${themeKey} theme`}
              />
            );
          })}
        </div>
      </div> */}

      {/* Dark Mode Toggle */}
      <button
        onClick={toggleDarkMode}
        className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-3"
        aria-label="Toggle dark mode"
      >
        {isDarkMode ? (
          <svg
            className="w-6 h-6 text-yellow-500"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z"
            />
          </svg>
        ) : (
          <svg
            className="w-6 h-6 text-gray-700"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"
            />
          </svg>
        )}
      </button>
    </div>
  );
};

export default DarkModeToggle; 